import{_ as o,o as e,c as n,a2 as a}from"./chunks/framework.CQjSGuJt.js";const u=JSON.parse('{"title":"Bộ marketing (quảng cáo)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/marketing.md","filePath":"guide/marketing.md"}'),d={name:"guide/marketing.md"};function c(r,t,i,g,h,l){return e(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="bo-marketing-quang-cao" tabindex="-1">Bộ marketing (quảng cáo) <a class="header-anchor" href="#bo-marketing-quang-cao" aria-label="Permalink to &quot;Bộ marketing (quảng cáo)&quot;">​</a></h1><p>Chuẩn bị sẵn để làm video quảng cáo / trang store. File tĩnh nằm trong <code>art/marketing/</code>:</p><table tabindex="0"><thead><tr><th>File</th><th>Kích thước</th><th>Dùng cho</th></tr></thead><tbody><tr><td><code>logo.png</code></td><td>1040 × 700, nền trong suốt</td><td>Logo &quot;FISH LOOP&quot; (chữ bong bóng + vòng ống kính có cá bơi)</td></tr><tr><td><code>icon.png</code></td><td>1024 × 1024, bo góc, nền trong suốt ngoài góc</td><td>Icon app / store</td></tr><tr><td><code>endcard.png</code></td><td>1080 × 1920</td><td>Ảnh tĩnh end card (outro video)</td></tr><tr><td><code>screen-win.png</code>, <code>screen-lose.png</code></td><td>1080 × 1920</td><td>Ảnh màn thắng / thua</td></tr></tbody></table><h2 id="canh-đong-đe-quay-man-hinh-lam-outro-video" tabindex="-1">Cảnh động (để quay màn hình làm outro video) <a class="header-anchor" href="#canh-đong-đe-quay-man-hinh-lam-outro-video" aria-label="Permalink to &quot;Cảnh động (để quay màn hình làm outro video)&quot;">​</a></h2><p>Mở game với tham số <code>promo</code>:</p><ul><li><code>&lt;pagesUrl&gt;/demo/?promo=endcard</code>: end card động: logo nảy, cá bơi vòng quanh logo, xe buýt nhận cá liên tục, nút <strong>CHƠI NGAY</strong> nhấp nháy + bàn tay bấm. Khung dọc 1080 × 1920, quay ~5–8 giây là đủ một vòng lặp.</li><li><code>?promo=logo</code>: chỉ logo (nền trong suốt).</li><li><code>?promo=icon</code>: icon app.</li></ul><p>Khi chạy <code>npm run dev</code>, gõ <code>await window.__promo.export()</code> trong console để xuất lại PNG vào <code>.snaps/</code> (rồi chép vào <code>art/marketing/</code>).</p><h2 id="thong-tin-game" tabindex="-1">Thông tin game <a class="header-anchor" href="#thong-tin-game" aria-label="Permalink to &quot;Thông tin game&quot;">​</a></h2><ul><li>Tên: <strong>Fish Loop</strong></li><li>Câu giới thiệu (tagline): <em>Xếp cá đúng màu – lấp đầy xe buýt!</em> (tiếng Anh: <em>Sort the fish, fill the bus!</em>)</li><li>Màu chủ đạo: xanh nước (#1aa0e6), tím xe buýt (#6b4fd8), cam cá hề (#ff8a1f), viền chữ tím đậm (#4b2bb5).</li></ul><p>Logo, icon và end card hiện vẽ bằng code (<code>src/game/Logo.ts</code>, <code>src/scenes/Promo.ts</code>). Khi có ảnh logo / ruy băng / cá vui – buồn từ ChatGPT (phiếu <code>art/requests/logo.md</code>, <code>art/requests/ui-kit.md</code>) thì thay vào.</p>',10)])])}const s=o(d,[["render",c]]);export{u as __pageData,s as default};
